package dev.eugheist.ttmodern;
final class BedrockVisualAudit {
 static void golden(){float[][] cases={{.2f,0,0,0,0},{1,.5f,1,1,0},{.2f,-.5f,.4f,.7f,1},{1,0,0,1,1}};String[] hashes={"703d62cfe8effc43c04653256b79bd893e249020109d268babbc749441fd08b7","84ab1006e2652495658f81282ae769348c293e99f7ce055226771cbf9970e271","703d62cfe8effc43c04653256b79bd893e249020109d268babbc749441fd08b7","dbd0df6870fa814a965a7023ea2ba387d0a623541eafa957e4b54a73dc3b3064"};try{for(int n=0;n<cases.length;n++){var c=cases[n];var bytes=java.nio.ByteBuffer.allocate(1024);for(int sky=0;sky<16;sky++)for(int block=0;block<16;block++)bytes.putInt(BedrockLightmap.color(block,sky,c[0],c[1],c[2],c[3],c[4],false));var hash=java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(bytes.array()));if(!hash.equals(hashes[n]))throw new IllegalStateException("TT bedrock light original oracle case "+n+" actual="+hash);}}catch(java.security.NoSuchAlgorithmException e){throw new IllegalStateException(e);}var fx=new BedrockDimensionClient();if(fx.skyType()!=net.minecraft.client.renderer.DimensionSpecialEffects.SkyType.NONE||!Float.isNaN(fx.getCloudHeight())||fx.isFoggyAt(0,0))throw new IllegalStateException("TT original non-surface sky/cloud/fog flags");var fog=fx.getBrightnessDependentFogColor(net.minecraft.world.phys.Vec3.ZERO,0);for(float brightness:new float[]{0,.5f,1})if(!fog.equals(fx.getBrightnessDependentFogColor(new net.minecraft.world.phys.Vec3(1,1,1),brightness)))throw new IllegalStateException("TT original constant purple fog");System.out.println("TT BEDROCK VISUAL CLIENT AUDIT: ALL PASS (independent original lightmap four full256pixel goldens/nightvision/gamma/darkening,non-surface sky/clouds,constant purple fog)");}
 static void world(net.minecraft.client.Minecraft mc){EnchanterClientAudit.check(mc.level.effects() instanceof BedrockDimensionClient,"native bedrock dimension effects registry selected");var light=mc.gameRenderer.lightTexture();light.tick();light.updateLightTexture(.5f);try{var field=net.minecraft.client.renderer.LightTexture.class.getDeclaredField("lightPixels");field.setAccessible(true);var pixels=(com.mojang.blaze3d.platform.NativeImage)field.get(light);for(int sky=0;sky<16;sky++)for(int block=0;block<16;block++)if(pixels.getPixelRGBA(block,sky)!=BedrockLightmap.nativeColor(mc,block,sky,.5f))throw new IllegalStateException("TT native bedrock light texture mismatch "+block+","+sky);}catch(ReflectiveOperationException e){throw new IllegalStateException(e);}EnchanterClientAudit.check(true,"actual native lightmap all256pixels match original arithmetic");}
}
